import { LucideIcon } from 'lucide-react';
import { cn } from '@/lib/utils';

interface StatCardProps {
  title: string;
  value: string | number;
  icon: LucideIcon;
  trend?: string;
  trendUp?: boolean;
  className?: string;
  color?: 'teal' | 'blue' | 'purple' | 'orange';
}

const colorMap = {
  teal: 'bg-teal-50 text-teal-600',
  blue: 'bg-blue-50 text-blue-600',
  purple: 'bg-purple-50 text-purple-600',
  orange: 'bg-orange-50 text-orange-600',
};

export function StatCard({ title, value, icon: Icon, trend, trendUp, className, color = 'teal' }: StatCardProps) {
  return (
    <div className={cn('rounded-xl border border-slate-100 bg-white p-5 shadow-sm', className)}>
      <div className="flex items-start justify-between">
        <div>
          <p className="text-xs font-medium text-slate-500">{title}</p>
          <p className="mt-2 text-2xl font-bold text-slate-900">{value}</p>
          {trend && (
            <p className={cn('mt-1 text-xs', trendUp ? 'text-emerald-600' : 'text-red-600')}>
              {trendUp ? '↑' : '↓'} {trend}
            </p>
          )}
        </div>
        <div className={cn('rounded-lg p-2.5', colorMap[color])}>
          <Icon size={22} />
        </div>
      </div>
    </div>
  );
}
