import { useState, useMemo } from 'react';
import { Plus, Search, Pencil, Trash2, CheckCircle } from 'lucide-react';
import { DataTable, type Column } from '@/components/DataTable';
import { Modal } from '@/components/Modal';
import { StatusBadge } from '@/components/StatusBadge';
import { useAppStore } from '@/stores/appStore';
import type { Agreement, AgreementStatus } from '@/types';
import { agreementStatusLabels } from '@/types';

const initialForm: Partial<Agreement> = {
  graduateId: '',
  enterpriseId: '',
  jobId: '',
  signDate: new Date().toISOString().slice(0, 10),
  status: 'draft',
  salary: '',
  workLocation: '',
};

const PAGE_SIZE = 6;

export function Agreements() {
  const { agreements, graduates, enterprises, jobs, addAgreement, updateAgreement, deleteAgreement } = useAppStore();
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('');
  const [page, setPage] = useState(1);
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<Agreement | null>(null);
  const [form, setForm] = useState<Partial<Agreement>>(initialForm);

  const filteredJobs = useMemo(() => {
    return jobs.filter((j) => j.status === 'published');
  }, [jobs]);

  const filtered = useMemo(() => {
    return agreements.filter((a) => {
      const g = graduates.find((x) => x.id === a.graduateId);
      const e = enterprises.find((x) => x.id === a.enterpriseId);
      const matchSearch =
        (g?.name.includes(search) ?? false) ||
        (e?.name.includes(search) ?? false);
      const matchStatus = statusFilter ? a.status === statusFilter : true;
      return matchSearch && matchStatus;
    });
  }, [agreements, graduates, enterprises, search, statusFilter]);

  const paged = useMemo(() => filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE), [filtered, page]);

  const openCreate = () => {
    setEditing(null);
    setForm({
      ...initialForm,
      graduateId: graduates[0]?.id ?? '',
      enterpriseId: enterprises[0]?.id ?? '',
      jobId: filteredJobs[0]?.id ?? '',
    });
    setModalOpen(true);
  };

  const openEdit = (a: Agreement) => {
    setEditing(a);
    setForm(a);
    setModalOpen(true);
  };

  const handleSubmit = (ev: React.FormEvent) => {
    ev.preventDefault();
    if (editing) {
      updateAgreement(editing.id, form);
    } else {
      addAgreement(form as Omit<Agreement, 'id'>);
    }
    setModalOpen(false);
    setForm(initialForm);
    setEditing(null);
  };

  const handleDelete = (id: string) => {
    if (confirm('确定删除该协议吗？')) deleteAgreement(id);
  };

  const handleApprove = (id: string) => updateAgreement(id, { status: 'approved' });
  const handleSign = (id: string) => updateAgreement(id, { status: 'signed' });

  const columns: Column<Agreement>[] = [
    {
      key: 'graduate',
      title: '毕业生',
      render: (a) => graduates.find((g) => g.id === a.graduateId)?.name ?? '-',
    },
    {
      key: 'enterprise',
      title: '用人单位',
      render: (a) => enterprises.find((e) => e.id === a.enterpriseId)?.name ?? '-',
    },
    {
      key: 'job',
      title: '岗位',
      render: (a) => jobs.find((j) => j.id === a.jobId)?.title ?? '-',
    },
    { key: 'signDate', title: '签约日期' },
    { key: 'salary', title: '薪资' },
    { key: 'workLocation', title: '工作地点' },
    {
      key: 'status',
      title: '协议状态',
      render: (a) => <StatusBadge status={a.status} label={agreementStatusLabels[a.status]} />,
    },
  ];

  return (
    <div className="space-y-5">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <h2 className="text-lg font-bold text-slate-900">协议签约</h2>
        <button
          onClick={openCreate}
          className="flex items-center justify-center gap-1.5 rounded-lg bg-teal-600 px-4 py-2 text-sm font-medium text-white hover:bg-teal-700"
        >
          <Plus size={16} /> 新增协议
        </button>
      </div>

      <div className="flex flex-col gap-3 sm:flex-row">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input
            type="text"
            value={search}
            onChange={(e) => { setSearch(e.target.value); setPage(1); }}
            placeholder="搜索毕业生、企业..."
            className="w-full rounded-lg border border-slate-200 py-2 pl-10 pr-4 text-sm outline-none focus:border-teal-500 focus:ring-2 focus:ring-teal-500/20"
          />
        </div>
        <select
          value={statusFilter}
          onChange={(e) => { setStatusFilter(e.target.value); setPage(1); }}
          className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm outline-none focus:border-teal-500"
        >
          <option value="">全部状态</option>
          {Object.entries(agreementStatusLabels).map(([key, label]) => (
            <option key={key} value={key}>{label}</option>
          ))}
        </select>
      </div>

      <DataTable
        columns={columns}
        data={paged}
        rowKey={(a) => a.id}
        actions={(a) => (
          <>
            {a.status === 'submitted' && (
              <button
                onClick={() => handleApprove(a.id)}
                className="rounded-lg p-1.5 text-slate-500 hover:bg-green-50 hover:text-green-600"
                title="审核通过"
              >
                <CheckCircle size={16} />
              </button>
            )}
            {a.status === 'approved' && (
              <button
                onClick={() => handleSign(a.id)}
                className="rounded-lg p-1.5 text-slate-500 hover:bg-teal-50 hover:text-teal-600"
                title="确认签约"
              >
                <CheckCircle size={16} />
              </button>
            )}
            <button
              onClick={() => openEdit(a)}
              className="rounded-lg p-1.5 text-slate-500 hover:bg-teal-50 hover:text-teal-600"
              title="编辑"
            >
              <Pencil size={16} />
            </button>
            <button
              onClick={() => handleDelete(a.id)}
              className="rounded-lg p-1.5 text-slate-500 hover:bg-red-50 hover:text-red-600"
              title="删除"
            >
              <Trash2 size={16} />
            </button>
          </>
        )}
        pagination={{
          page,
          pageSize: PAGE_SIZE,
          total: filtered.length,
          onChange: setPage,
        }}
      />

      <Modal open={modalOpen} onClose={() => setModalOpen(false)} title={editing ? '编辑协议' : '新增协议'} className="max-w-xl">
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="mb-1 block text-xs font-medium text-slate-600">毕业生</label>
            <select
              required
              value={form.graduateId}
              onChange={(e) => setForm({ ...form, graduateId: e.target.value })}
              className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
            >
              <option value="">请选择毕业生</option>
              {graduates.map((g) => (
                <option key={g.id} value={g.id}>{`${g.name} (${g.studentId})`}</option>
              ))}
            </select>
          </div>
          <div>
            <label className="mb-1 block text-xs font-medium text-slate-600">用人单位</label>
            <select
              required
              value={form.enterpriseId}
              onChange={(e) => setForm({ ...form, enterpriseId: e.target.value })}
              className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
            >
              <option value="">请选择企业</option>
              {enterprises.filter((e) => e.status === 'approved').map((e) => (
                <option key={e.id} value={e.id}>{e.name}</option>
              ))}
            </select>
          </div>
          <div>
            <label className="mb-1 block text-xs font-medium text-slate-600">岗位</label>
            <select
              required
              value={form.jobId}
              onChange={(e) => setForm({ ...form, jobId: e.target.value })}
              className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
            >
              <option value="">请选择岗位</option>
              {filteredJobs.map((j) => (
                <option key={j.id} value={j.id}>{j.title}</option>
              ))}
            </select>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="mb-1 block text-xs font-medium text-slate-600">签约日期</label>
              <input
                type="date"
                value={form.signDate}
                onChange={(e) => setForm({ ...form, signDate: e.target.value })}
                className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
              />
            </div>
            <div>
              <label className="mb-1 block text-xs font-medium text-slate-600">薪资</label>
              <input
                value={form.salary}
                onChange={(e) => setForm({ ...form, salary: e.target.value })}
                className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
              />
            </div>
          </div>
          <div>
            <label className="mb-1 block text-xs font-medium text-slate-600">工作地点</label>
            <input
              value={form.workLocation}
              onChange={(e) => setForm({ ...form, workLocation: e.target.value })}
              className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
            />
          </div>
          <div>
            <label className="mb-1 block text-xs font-medium text-slate-600">协议状态</label>
            <select
              value={form.status}
              onChange={(e) => setForm({ ...form, status: e.target.value as AgreementStatus })}
              className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
            >
              {Object.entries(agreementStatusLabels).map(([key, label]) => (
                <option key={key} value={key}>{label}</option>
              ))}
            </select>
          </div>
          <div className="flex justify-end gap-3 pt-2">
            <button
              type="button"
              onClick={() => setModalOpen(false)}
              className="rounded-lg border border-slate-200 px-4 py-2 text-sm font-medium text-slate-600 hover:bg-slate-50"
            >
              取消
            </button>
            <button
              type="submit"
              className="rounded-lg bg-teal-600 px-4 py-2 text-sm font-medium text-white hover:bg-teal-700"
            >
              保存
            </button>
          </div>
        </form>
      </Modal>
    </div>
  );
}
