import { useState, useMemo } from 'react';
import { Plus, Search, Pencil, Trash2 } from 'lucide-react';
import { DataTable, type Column } from '@/components/DataTable';
import { Modal } from '@/components/Modal';
import { StatusBadge } from '@/components/StatusBadge';
import { useAppStore } from '@/stores/appStore';
import type { TrackingRecord, EmploymentStatus } from '@/types';
import { employmentStatusLabels } from '@/types';

const initialForm: Partial<TrackingRecord> = {
  graduateId: '',
  trackDate: new Date().toISOString().slice(0, 10),
  status: 'employed',
  note: '',
  contactResult: 'reachable',
};

const PAGE_SIZE = 6;

export function Tracking() {
  const { tracking, graduates, addTracking, updateTracking, deleteTracking } = useAppStore();
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<TrackingRecord | null>(null);
  const [form, setForm] = useState<Partial<TrackingRecord>>(initialForm);

  const filtered = useMemo(() => {
    return tracking.filter((t) => {
      const g = graduates.find((x) => x.id === t.graduateId);
      return g?.name.includes(search) ?? false;
    });
  }, [tracking, graduates, search]);

  const paged = useMemo(() => filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE), [filtered, page]);

  const openCreate = () => {
    setEditing(null);
    setForm({ ...initialForm, graduateId: graduates[0]?.id ?? '' });
    setModalOpen(true);
  };

  const openEdit = (t: TrackingRecord) => {
    setEditing(t);
    setForm(t);
    setModalOpen(true);
  };

  const handleSubmit = (ev: React.FormEvent) => {
    ev.preventDefault();
    if (editing) {
      updateTracking(editing.id, form);
    } else {
      addTracking(form as Omit<TrackingRecord, 'id'>);
    }
    setModalOpen(false);
    setForm(initialForm);
    setEditing(null);
  };

  const handleDelete = (id: string) => {
    if (confirm('确定删除该跟踪记录吗？')) deleteTracking(id);
  };

  const columns: Column<TrackingRecord>[] = [
    {
      key: 'graduate',
      title: '毕业生',
      render: (t) => graduates.find((g) => g.id === t.graduateId)?.name ?? '-',
    },
    { key: 'trackDate', title: '跟踪日期' },
    {
      key: 'status',
      title: '当前状态',
      render: (t) => <StatusBadge status={t.status} label={employmentStatusLabels[t.status]} />,
    },
    {
      key: 'contactResult',
      title: '联系结果',
      render: (t) =>
        t.contactResult === 'reachable'
          ? '已联系上'
          : t.contactResult === 'unreachable'
          ? '未联系上'
          : '无人接听',
    },
    { key: 'note', title: '备注' },
  ];

  return (
    <div className="space-y-5">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <h2 className="text-lg font-bold text-slate-900">就业跟踪</h2>
        <button
          onClick={openCreate}
          className="flex items-center justify-center gap-1.5 rounded-lg bg-teal-600 px-4 py-2 text-sm font-medium text-white hover:bg-teal-700"
        >
          <Plus size={16} /> 新增跟踪记录
        </button>
      </div>

      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
        <input
          type="text"
          value={search}
          onChange={(e) => { setSearch(e.target.value); setPage(1); }}
          placeholder="搜索毕业生姓名..."
          className="w-full rounded-lg border border-slate-200 py-2 pl-10 pr-4 text-sm outline-none focus:border-teal-500 focus:ring-2 focus:ring-teal-500/20"
        />
      </div>

      <DataTable
        columns={columns}
        data={paged}
        rowKey={(t) => t.id}
        actions={(t) => (
          <>
            <button
              onClick={() => openEdit(t)}
              className="rounded-lg p-1.5 text-slate-500 hover:bg-teal-50 hover:text-teal-600"
              title="编辑"
            >
              <Pencil size={16} />
            </button>
            <button
              onClick={() => handleDelete(t.id)}
              className="rounded-lg p-1.5 text-slate-500 hover:bg-red-50 hover:text-red-600"
              title="删除"
            >
              <Trash2 size={16} />
            </button>
          </>
        )}
        pagination={{
          page,
          pageSize: PAGE_SIZE,
          total: filtered.length,
          onChange: setPage,
        }}
      />

      <Modal open={modalOpen} onClose={() => setModalOpen(false)} title={editing ? '编辑跟踪记录' : '新增跟踪记录'}>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="mb-1 block text-xs font-medium text-slate-600">毕业生</label>
            <select
              required
              value={form.graduateId}
              onChange={(e) => setForm({ ...form, graduateId: e.target.value })}
              className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
            >
              <option value="">请选择毕业生</option>
              {graduates.map((g) => (
                <option key={g.id} value={g.id}>{`${g.name} (${g.studentId})`}</option>
              ))}
            </select>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="mb-1 block text-xs font-medium text-slate-600">跟踪日期</label>
              <input
                type="date"
                value={form.trackDate}
                onChange={(e) => setForm({ ...form, trackDate: e.target.value })}
                className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
              />
            </div>
            <div>
              <label className="mb-1 block text-xs font-medium text-slate-600">当前状态</label>
              <select
                value={form.status}
                onChange={(e) => setForm({ ...form, status: e.target.value as EmploymentStatus })}
                className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
              >
                {Object.entries(employmentStatusLabels).map(([key, label]) => (
                  <option key={key} value={key}>{label}</option>
                ))}
              </select>
            </div>
          </div>
          <div>
            <label className="mb-1 block text-xs font-medium text-slate-600">联系结果</label>
            <select
              value={form.contactResult}
              onChange={(e) => setForm({ ...form, contactResult: e.target.value as 'reachable' | 'unreachable' | 'no_answer' })}
              className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
            >
              <option value="reachable">已联系上</option>
              <option value="no_answer">无人接听</option>
              <option value="unreachable">未联系上</option>
            </select>
          </div>
          <div>
            <label className="mb-1 block text-xs font-medium text-slate-600">备注</label>
            <textarea
              value={form.note}
              onChange={(e) => setForm({ ...form, note: e.target.value })}
              rows={3}
              className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
            />
          </div>
          <div className="flex justify-end gap-3 pt-2">
            <button
              type="button"
              onClick={() => setModalOpen(false)}
              className="rounded-lg border border-slate-200 px-4 py-2 text-sm font-medium text-slate-600 hover:bg-slate-50"
            >
              取消
            </button>
            <button
              type="submit"
              className="rounded-lg bg-teal-600 px-4 py-2 text-sm font-medium text-white hover:bg-teal-700"
            >
              保存
            </button>
          </div>
        </form>
      </Modal>
    </div>
  );
}
