import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Building2, User, Lock, Eye, EyeOff, Info } from 'lucide-react';
import { useAppStore } from '@/stores/appStore';
import { cn } from '@/lib/utils';

export function Login() {
  const navigate = useNavigate();
  const { login } = useAppStore();
  const [username, setUsername] = useState('admin');
  const [password, setPassword] = useState('123456');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    setTimeout(() => {
      const ok = login(username, password);
      if (ok) {
        navigate('/', { replace: true });
      } else {
        setError('用户名或密码错误');
      }
      setLoading(false);
    }, 400);
  };

  return (
    <div className="relative flex min-h-screen w-full items-center justify-center overflow-hidden bg-[#0f172a]">
      {/* Background gradients */}
      <div className="absolute -left-20 -top-20 h-[500px] w-[500px] rounded-full bg-teal-500/20 blur-[120px]" />
      <div className="absolute -bottom-20 -right-20 h-[500px] w-[500px] rounded-full bg-emerald-500/15 blur-[120px]" />
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_30%_30%,rgba(13,148,136,0.12),transparent_50%)]" />

      <div className="relative z-10 mx-4 grid w-full max-w-5xl grid-cols-1 gap-8 rounded-3xl bg-white/5 p-6 backdrop-blur-sm lg:grid-cols-2 lg:p-10">
        {/* Left brand area */}
        <div className="flex flex-col justify-center rounded-2xl bg-slate-900/60 p-8 text-white">
          <span className="mb-6 w-fit rounded-full border border-teal-500/30 bg-teal-500/10 px-4 py-1.5 text-xs font-medium tracking-wide text-teal-300">
            CAMPUS EMPLOYMENT OS
          </span>
          <h1 className="text-3xl font-bold leading-tight lg:text-4xl">
            高校毕业生就业跟踪管理系统
          </h1>
          <p className="mt-5 text-sm leading-relaxed text-slate-300">
            覆盖毕业生台账、企业审核、岗位发布、协议签约、派遣办理与就业跟踪，适合课程设计展示，也方便继续扩展为真实业务系统。
          </p>
          <div className="mt-8 grid grid-cols-3 gap-4">
            <div className="rounded-xl bg-slate-800/60 p-4">
              <p className="text-2xl font-bold text-teal-400">9</p>
              <p className="mt-1 text-xs text-slate-400">核心业务模块</p>
            </div>
            <div className="rounded-xl bg-slate-800/60 p-4">
              <p className="text-2xl font-bold text-teal-400">24</p>
              <p className="mt-1 text-xs text-slate-400">示例毕业生数据</p>
            </div>
            <div className="rounded-xl bg-slate-800/60 p-4">
              <p className="text-xl font-bold text-teal-400">Local</p>
              <p className="mt-1 text-xs text-slate-400">数据自动持久化</p>
            </div>
          </div>
        </div>

        {/* Right login form */}
        <div className="flex items-center justify-center">
          <div className="w-full max-w-sm rounded-2xl bg-white p-8 shadow-2xl">
            <div className="flex flex-col items-center">
              <div className="flex h-14 w-14 items-center justify-center rounded-xl bg-teal-50 text-teal-600">
                <Building2 size={32} />
              </div>
              <h2 className="mt-4 text-xl font-bold text-slate-900">欢迎登录</h2>
              <p className="mt-1 text-xs text-slate-500">
                Graduate Employment Tracking Management System
              </p>
            </div>

            <form onSubmit={handleSubmit} className="mt-8 space-y-4">
              <div className="relative">
                <User className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input
                  type="text"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  placeholder="请输入用户名"
                  className="w-full rounded-lg border border-slate-200 bg-white py-2.5 pl-10 pr-4 text-sm text-slate-700 outline-none transition-colors focus:border-teal-500 focus:ring-2 focus:ring-teal-500/20"
                />
              </div>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="请输入密码"
                  className="w-full rounded-lg border border-slate-200 bg-white py-2.5 pl-10 pr-10 text-sm text-slate-700 outline-none transition-colors focus:border-teal-500 focus:ring-2 focus:ring-teal-500/20"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>

              {error && (
                <p className="text-xs text-red-500">{error}</p>
              )}

              <button
                type="submit"
                disabled={loading}
                className={cn(
                  'w-full rounded-lg bg-gradient-to-r from-teal-600 to-emerald-600 py-2.5 text-sm font-medium text-white shadow-md transition-all hover:from-teal-700 hover:to-emerald-700 active:scale-[0.98]',
                  loading && 'opacity-70 cursor-wait'
                )}
              >
                {loading ? '登录中...' : '登 录'}
              </button>
            </form>

            <div className="mt-5 flex items-start gap-2 rounded-lg bg-slate-50 p-3">
              <Info size={16} className="mt-0.5 shrink-0 text-slate-400" />
              <div>
                <p className="text-xs text-slate-600">
                  演示账号：admin / 123456（管理员）
                </p>
              </div>
            </div>

            <p className="mt-4 text-center text-xs text-slate-400">
              登录后你可以直接修改数据，页面刷新后仍会保留当前演示状态。
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}
