import { useState, useMemo } from 'react';
import { Plus, Search, Pencil, Trash2 } from 'lucide-react';
import { DataTable, type Column } from '@/components/DataTable';
import { Modal } from '@/components/Modal';
import { StatusBadge } from '@/components/StatusBadge';
import { useAppStore } from '@/stores/appStore';
import type { Job, JobStatus } from '@/types';
import { jobStatusLabels } from '@/types';

const initialForm: Partial<Job> = {
  enterpriseId: '',
  title: '',
  department: '',
  salary: '',
  location: '',
  requirements: '',
  status: 'published',
  publishDate: new Date().toISOString().slice(0, 10),
};

const PAGE_SIZE = 6;

export function Jobs() {
  const { jobs, enterprises, addJob, updateJob, deleteJob } = useAppStore();
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('');
  const [page, setPage] = useState(1);
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<Job | null>(null);
  const [form, setForm] = useState<Partial<Job>>(initialForm);

  const approvedEnterprises = enterprises.filter((e) => e.status === 'approved');

  const filtered = useMemo(() => {
    return jobs.filter((j) => {
      const matchSearch = j.title.includes(search) || j.location.includes(search);
      const matchStatus = statusFilter ? j.status === statusFilter : true;
      return matchSearch && matchStatus;
    });
  }, [jobs, search, statusFilter]);

  const paged = useMemo(() => {
    return filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);
  }, [filtered, page]);

  const openCreate = () => {
    setEditing(null);
    setForm({ ...initialForm, enterpriseId: approvedEnterprises[0]?.id ?? '' });
    setModalOpen(true);
  };

  const openEdit = (j: Job) => {
    setEditing(j);
    setForm(j);
    setModalOpen(true);
  };

  const handleSubmit = (ev: React.FormEvent) => {
    ev.preventDefault();
    if (editing) {
      updateJob(editing.id, form);
    } else {
      addJob(form as Omit<Job, 'id'>);
    }
    setModalOpen(false);
    setForm(initialForm);
    setEditing(null);
  };

  const handleDelete = (id: string) => {
    if (confirm('确定删除该岗位吗？')) deleteJob(id);
  };

  const columns: Column<Job>[] = [
    { key: 'title', title: '岗位名称' },
    {
      key: 'enterpriseId',
      title: '所属企业',
      render: (j) => enterprises.find((e) => e.id === j.enterpriseId)?.name ?? '-',
    },
    { key: 'department', title: '部门' },
    { key: 'salary', title: '薪资范围' },
    { key: 'location', title: '工作地点' },
    { key: 'publishDate', title: '发布日期' },
    {
      key: 'status',
      title: '状态',
      render: (j) => <StatusBadge status={j.status} label={jobStatusLabels[j.status]} />,
    },
  ];

  return (
    <div className="space-y-5">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <h2 className="text-lg font-bold text-slate-900">岗位发布</h2>
        <button
          onClick={openCreate}
          className="flex items-center justify-center gap-1.5 rounded-lg bg-teal-600 px-4 py-2 text-sm font-medium text-white hover:bg-teal-700"
        >
          <Plus size={16} /> 新增岗位
        </button>
      </div>

      <div className="flex flex-col gap-3 sm:flex-row">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input
            type="text"
            value={search}
            onChange={(e) => { setSearch(e.target.value); setPage(1); }}
            placeholder="搜索岗位名称、工作地点..."
            className="w-full rounded-lg border border-slate-200 py-2 pl-10 pr-4 text-sm outline-none focus:border-teal-500 focus:ring-2 focus:ring-teal-500/20"
          />
        </div>
        <select
          value={statusFilter}
          onChange={(e) => { setStatusFilter(e.target.value); setPage(1); }}
          className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm outline-none focus:border-teal-500"
        >
          <option value="">全部状态</option>
          {Object.entries(jobStatusLabels).map(([key, label]) => (
            <option key={key} value={key}>{label}</option>
          ))}
        </select>
      </div>

      <DataTable
        columns={columns}
        data={paged}
        rowKey={(j) => j.id}
        actions={(j) => (
          <>
            <button
              onClick={() => openEdit(j)}
              className="rounded-lg p-1.5 text-slate-500 hover:bg-teal-50 hover:text-teal-600"
              title="编辑"
            >
              <Pencil size={16} />
            </button>
            <button
              onClick={() => handleDelete(j.id)}
              className="rounded-lg p-1.5 text-slate-500 hover:bg-red-50 hover:text-red-600"
              title="删除"
            >
              <Trash2 size={16} />
            </button>
          </>
        )}
        pagination={{
          page,
          pageSize: PAGE_SIZE,
          total: filtered.length,
          onChange: setPage,
        }}
      />

      <Modal open={modalOpen} onClose={() => setModalOpen(false)} title={editing ? '编辑岗位' : '新增岗位'} className="max-w-xl">
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="mb-1 block text-xs font-medium text-slate-600">所属企业</label>
            <select
              required
              value={form.enterpriseId}
              onChange={(e) => setForm({ ...form, enterpriseId: e.target.value })}
              className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
            >
              <option value="">请选择企业</option>
              {approvedEnterprises.map((e) => (
                <option key={e.id} value={e.id}>{e.name}</option>
              ))}
            </select>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="mb-1 block text-xs font-medium text-slate-600">岗位名称</label>
              <input
                required
                value={form.title}
                onChange={(e) => setForm({ ...form, title: e.target.value })}
                className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
              />
            </div>
            <div>
              <label className="mb-1 block text-xs font-medium text-slate-600">部门</label>
              <input
                value={form.department}
                onChange={(e) => setForm({ ...form, department: e.target.value })}
                className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
              />
            </div>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="mb-1 block text-xs font-medium text-slate-600">薪资范围</label>
              <input
                value={form.salary}
                onChange={(e) => setForm({ ...form, salary: e.target.value })}
                className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
              />
            </div>
            <div>
              <label className="mb-1 block text-xs font-medium text-slate-600">工作地点</label>
              <input
                value={form.location}
                onChange={(e) => setForm({ ...form, location: e.target.value })}
                className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
              />
            </div>
          </div>
          <div>
            <label className="mb-1 block text-xs font-medium text-slate-600">岗位要求</label>
            <textarea
              value={form.requirements}
              onChange={(e) => setForm({ ...form, requirements: e.target.value })}
              rows={3}
              className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
            />
          </div>
          <div>
            <label className="mb-1 block text-xs font-medium text-slate-600">发布状态</label>
            <select
              value={form.status}
              onChange={(e) => setForm({ ...form, status: e.target.value as JobStatus })}
              className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
            >
              {Object.entries(jobStatusLabels).map(([key, label]) => (
                <option key={key} value={key}>{label}</option>
              ))}
            </select>
          </div>
          <div className="flex justify-end gap-3 pt-2">
            <button
              type="button"
              onClick={() => setModalOpen(false)}
              className="rounded-lg border border-slate-200 px-4 py-2 text-sm font-medium text-slate-600 hover:bg-slate-50"
            >
              取消
            </button>
            <button
              type="submit"
              className="rounded-lg bg-teal-600 px-4 py-2 text-sm font-medium text-white hover:bg-teal-700"
            >
              保存
            </button>
          </div>
        </form>
      </Modal>
    </div>
  );
}
