import { useState, useMemo } from 'react';
import { Plus, Search, CheckCircle, XCircle, Pencil, Trash2 } from 'lucide-react';
import { DataTable, type Column } from '@/components/DataTable';
import { Modal } from '@/components/Modal';
import { StatusBadge } from '@/components/StatusBadge';
import { useAppStore } from '@/stores/appStore';
import type { Enterprise, EnterpriseStatus } from '@/types';
import { enterpriseStatusLabels } from '@/types';

const initialForm: Partial<Enterprise> = {
  name: '',
  industry: '',
  scale: '',
  contactPerson: '',
  contactPhone: '',
  status: 'pending',
  applyDate: new Date().toISOString().slice(0, 10),
};

const PAGE_SIZE = 6;

export function Enterprises() {
  const { enterprises, addEnterprise, updateEnterprise, deleteEnterprise } = useAppStore();
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('');
  const [page, setPage] = useState(1);
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<Enterprise | null>(null);
  const [form, setForm] = useState<Partial<Enterprise>>(initialForm);

  const filtered = useMemo(() => {
    return enterprises.filter((e) => {
      const matchSearch = e.name.includes(search) || e.industry.includes(search);
      const matchStatus = statusFilter ? e.status === statusFilter : true;
      return matchSearch && matchStatus;
    });
  }, [enterprises, search, statusFilter]);

  const paged = useMemo(() => {
    return filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);
  }, [filtered, page]);

  const openCreate = () => {
    setEditing(null);
    setForm(initialForm);
    setModalOpen(true);
  };

  const openEdit = (e: Enterprise) => {
    setEditing(e);
    setForm(e);
    setModalOpen(true);
  };

  const handleSubmit = (ev: React.FormEvent) => {
    ev.preventDefault();
    if (editing) {
      updateEnterprise(editing.id, form);
    } else {
      addEnterprise(form as Omit<Enterprise, 'id'>);
    }
    setModalOpen(false);
    setForm(initialForm);
    setEditing(null);
  };

  const handleDelete = (id: string) => {
    if (confirm('确定删除该企业吗？')) deleteEnterprise(id);
  };

  const handleApprove = (id: string) => updateEnterprise(id, { status: 'approved' });
  const handleReject = (id: string) => updateEnterprise(id, { status: 'rejected' });

  const columns: Column<Enterprise>[] = [
    { key: 'name', title: '企业名称' },
    { key: 'industry', title: '所属行业' },
    { key: 'scale', title: '企业规模' },
    { key: 'contactPerson', title: '联系人' },
    { key: 'contactPhone', title: '联系电话' },
    { key: 'applyDate', title: '申请日期' },
    {
      key: 'status',
      title: '审核状态',
      render: (e) => <StatusBadge status={e.status} label={enterpriseStatusLabels[e.status]} />,
    },
  ];

  return (
    <div className="space-y-5">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <h2 className="text-lg font-bold text-slate-900">企业审核</h2>
        <button
          onClick={openCreate}
          className="flex items-center justify-center gap-1.5 rounded-lg bg-teal-600 px-4 py-2 text-sm font-medium text-white hover:bg-teal-700"
        >
          <Plus size={16} /> 新增企业
        </button>
      </div>

      <div className="flex flex-col gap-3 sm:flex-row">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input
            type="text"
            value={search}
            onChange={(e) => { setSearch(e.target.value); setPage(1); }}
            placeholder="搜索企业名称、行业..."
            className="w-full rounded-lg border border-slate-200 py-2 pl-10 pr-4 text-sm outline-none focus:border-teal-500 focus:ring-2 focus:ring-teal-500/20"
          />
        </div>
        <select
          value={statusFilter}
          onChange={(e) => { setStatusFilter(e.target.value); setPage(1); }}
          className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm outline-none focus:border-teal-500"
        >
          <option value="">全部状态</option>
          {Object.entries(enterpriseStatusLabels).map(([key, label]) => (
            <option key={key} value={key}>{label}</option>
          ))}
        </select>
      </div>

      <DataTable
        columns={columns}
        data={paged}
        rowKey={(e) => e.id}
        actions={(e) => (
          <>
            {e.status === 'pending' && (
              <>
                <button
                  onClick={() => handleApprove(e.id)}
                  className="rounded-lg p-1.5 text-slate-500 hover:bg-green-50 hover:text-green-600"
                  title="通过"
                >
                  <CheckCircle size={16} />
                </button>
                <button
                  onClick={() => handleReject(e.id)}
                  className="rounded-lg p-1.5 text-slate-500 hover:bg-red-50 hover:text-red-600"
                  title="拒绝"
                >
                  <XCircle size={16} />
                </button>
              </>
            )}
            <button
              onClick={() => openEdit(e)}
              className="rounded-lg p-1.5 text-slate-500 hover:bg-teal-50 hover:text-teal-600"
              title="编辑"
            >
              <Pencil size={16} />
            </button>
            <button
              onClick={() => handleDelete(e.id)}
              className="rounded-lg p-1.5 text-slate-500 hover:bg-red-50 hover:text-red-600"
              title="删除"
            >
              <Trash2 size={16} />
            </button>
          </>
        )}
        pagination={{
          page,
          pageSize: PAGE_SIZE,
          total: filtered.length,
          onChange: setPage,
        }}
      />

      <Modal open={modalOpen} onClose={() => setModalOpen(false)} title={editing ? '编辑企业' : '新增企业'}>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="mb-1 block text-xs font-medium text-slate-600">企业名称</label>
            <input
              required
              value={form.name}
              onChange={(e) => setForm({ ...form, name: e.target.value })}
              className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
            />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="mb-1 block text-xs font-medium text-slate-600">所属行业</label>
              <input
                value={form.industry}
                onChange={(e) => setForm({ ...form, industry: e.target.value })}
                className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
              />
            </div>
            <div>
              <label className="mb-1 block text-xs font-medium text-slate-600">企业规模</label>
              <input
                value={form.scale}
                onChange={(e) => setForm({ ...form, scale: e.target.value })}
                className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
              />
            </div>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="mb-1 block text-xs font-medium text-slate-600">联系人</label>
              <input
                value={form.contactPerson}
                onChange={(e) => setForm({ ...form, contactPerson: e.target.value })}
                className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
              />
            </div>
            <div>
              <label className="mb-1 block text-xs font-medium text-slate-600">联系电话</label>
              <input
                value={form.contactPhone}
                onChange={(e) => setForm({ ...form, contactPhone: e.target.value })}
                className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
              />
            </div>
          </div>
          <div>
            <label className="mb-1 block text-xs font-medium text-slate-600">审核状态</label>
            <select
              value={form.status}
              onChange={(e) => setForm({ ...form, status: e.target.value as EnterpriseStatus })}
              className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
            >
              {Object.entries(enterpriseStatusLabels).map(([key, label]) => (
                <option key={key} value={key}>{label}</option>
              ))}
            </select>
          </div>
          <div className="flex justify-end gap-3 pt-2">
            <button
              type="button"
              onClick={() => setModalOpen(false)}
              className="rounded-lg border border-slate-200 px-4 py-2 text-sm font-medium text-slate-600 hover:bg-slate-50"
            >
              取消
            </button>
            <button
              type="submit"
              className="rounded-lg bg-teal-600 px-4 py-2 text-sm font-medium text-white hover:bg-teal-700"
            >
              保存
            </button>
          </div>
        </form>
      </Modal>
    </div>
  );
}
