import { create } from 'zustand';
import type {
  AppData,
  Graduate,
  Enterprise,
  Job,
  Agreement,
  Dispatch,
  TrackingRecord,
  SystemSettings,
} from '@/types';
import { loadData, saveData, setUser, generateId, resetData } from '@/utils/storage';
import { defaultUser } from '@/utils/mockData';

interface AppState extends AppData {
  login: (username: string, password: string) => boolean;
  logout: () => void;
  addGraduate: (graduate: Omit<Graduate, 'id' | 'createdAt'>) => void;
  updateGraduate: (id: string, graduate: Partial<Graduate>) => void;
  deleteGraduate: (id: string) => void;
  addEnterprise: (enterprise: Omit<Enterprise, 'id'>) => void;
  updateEnterprise: (id: string, enterprise: Partial<Enterprise>) => void;
  deleteEnterprise: (id: string) => void;
  addJob: (job: Omit<Job, 'id'>) => void;
  updateJob: (id: string, job: Partial<Job>) => void;
  deleteJob: (id: string) => void;
  addAgreement: (agreement: Omit<Agreement, 'id'>) => void;
  updateAgreement: (id: string, agreement: Partial<Agreement>) => void;
  deleteAgreement: (id: string) => void;
  addDispatch: (dispatch: Omit<Dispatch, 'id'>) => void;
  updateDispatch: (id: string, dispatch: Partial<Dispatch>) => void;
  deleteDispatch: (id: string) => void;
  addTracking: (tracking: Omit<TrackingRecord, 'id'>) => void;
  updateTracking: (id: string, tracking: Partial<TrackingRecord>) => void;
  deleteTracking: (id: string) => void;
  updateSettings: (settings: SystemSettings) => void;
  resetAllData: () => void;
  refresh: () => void;
}

const initial = loadData();

const sync = (state: Partial<AppData>) => {
  saveData(state);
  return state;
};

export const useAppStore = create<AppState>((set) => ({
  ...initial,

  refresh: () => set(loadData()),

  login: (username, password) => {
    if (username === 'admin' && password === '123456') {
      setUser(defaultUser);
      set({ user: defaultUser });
      return true;
    }
    return false;
  },

  logout: () => {
    setUser(null);
    set({ user: null });
  },

  addGraduate: (graduate) => {
    const item: Graduate = { ...graduate, id: generateId('g'), createdAt: new Date().toISOString().slice(0, 10) };
    set((state) => {
      const graduates = [...state.graduates, item];
      return sync({ graduates });
    });
  },

  updateGraduate: (id, graduate) => {
    set((state) => {
      const graduates = state.graduates.map((g) => (g.id === id ? { ...g, ...graduate } : g));
      return sync({ graduates });
    });
  },

  deleteGraduate: (id) => {
    set((state) => {
      const graduates = state.graduates.filter((g) => g.id !== id);
      return sync({ graduates });
    });
  },

  addEnterprise: (enterprise) => {
    const item: Enterprise = { ...enterprise, id: generateId('e') };
    set((state) => {
      const enterprises = [...state.enterprises, item];
      return sync({ enterprises });
    });
  },

  updateEnterprise: (id, enterprise) => {
    set((state) => {
      const enterprises = state.enterprises.map((e) => (e.id === id ? { ...e, ...enterprise } : e));
      return sync({ enterprises });
    });
  },

  deleteEnterprise: (id) => {
    set((state) => {
      const enterprises = state.enterprises.filter((e) => e.id !== id);
      return sync({ enterprises });
    });
  },

  addJob: (job) => {
    const item: Job = { ...job, id: generateId('j') };
    set((state) => {
      const jobs = [...state.jobs, item];
      return sync({ jobs });
    });
  },

  updateJob: (id, job) => {
    set((state) => {
      const jobs = state.jobs.map((j) => (j.id === id ? { ...j, ...job } : j));
      return sync({ jobs });
    });
  },

  deleteJob: (id) => {
    set((state) => {
      const jobs = state.jobs.filter((j) => j.id !== id);
      return sync({ jobs });
    });
  },

  addAgreement: (agreement) => {
    const item: Agreement = { ...agreement, id: generateId('a') };
    set((state) => {
      const agreements = [...state.agreements, item];
      return sync({ agreements });
    });
  },

  updateAgreement: (id, agreement) => {
    set((state) => {
      const agreements = state.agreements.map((a) => (a.id === id ? { ...a, ...agreement } : a));
      return sync({ agreements });
    });
  },

  deleteAgreement: (id) => {
    set((state) => {
      const agreements = state.agreements.filter((a) => a.id !== id);
      return sync({ agreements });
    });
  },

  addDispatch: (dispatch) => {
    const item: Dispatch = { ...dispatch, id: generateId('d') };
    set((state) => {
      const dispatches = [...state.dispatches, item];
      return sync({ dispatches });
    });
  },

  updateDispatch: (id, dispatch) => {
    set((state) => {
      const dispatches = state.dispatches.map((d) => (d.id === id ? { ...d, ...dispatch } : d));
      return sync({ dispatches });
    });
  },

  deleteDispatch: (id) => {
    set((state) => {
      const dispatches = state.dispatches.filter((d) => d.id !== id);
      return sync({ dispatches });
    });
  },

  addTracking: (tracking) => {
    const item: TrackingRecord = { ...tracking, id: generateId('t') };
    set((state) => {
      const trackingList = [...state.tracking, item];
      return sync({ tracking: trackingList });
    });
  },

  updateTracking: (id, tracking) => {
    set((state) => {
      const trackingList = state.tracking.map((t) => (t.id === id ? { ...t, ...tracking } : t));
      return sync({ tracking: trackingList });
    });
  },

  deleteTracking: (id) => {
    set((state) => {
      const trackingList = state.tracking.filter((t) => t.id !== id);
      return sync({ tracking: trackingList });
    });
  },

  updateSettings: (settings) => {
    set(() => sync({ settings }));
  },

  resetAllData: () => {
    resetData();
    set({ ...loadData(), user: null });
  },
}));
