import { useMemo } from 'react';
import {
  Users,
  Building2,
  Briefcase,
  ClipboardList,
  TrendingUp,
  AlertCircle,
} from 'lucide-react';
import { StatCard } from '@/components/StatCard';
import { useAppStore } from '@/stores/appStore';
import { employmentStatusLabels, agreementStatusLabels } from '@/types';
import {
  PieChart,
  Pie,
  Cell,
  ResponsiveContainer,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
  Legend,
} from 'recharts';

const COLORS = ['#0d9488', '#3b82f6', '#8b5cf6', '#f59e0b', '#ef4444'];

export function Dashboard() {
  const { graduates, enterprises, jobs, agreements, dispatches, tracking } = useAppStore();

  const employedCount = graduates.filter((g) => g.status === 'employed').length;
  const unemployedCount = graduates.filter((g) => g.status === 'unemployed').length;
  const pendingEnterprises = enterprises.filter((e) => e.status === 'pending').length;
  const pendingAgreements = agreements.filter((a) => a.status === 'submitted').length;
  const pendingDispatches = dispatches.filter((d) => d.status === 'pending').length;

  const statusData = useMemo(() => {
    const map: Record<string, number> = {};
    graduates.forEach((g) => {
      map[g.status] = (map[g.status] || 0) + 1;
    });
    return Object.entries(map).map(([key, value]) => ({
      name: employmentStatusLabels[key as keyof typeof employmentStatusLabels] ?? key,
      value,
    }));
  }, [graduates]);

  const collegeData = useMemo(() => {
    const map: Record<string, number> = {};
    graduates.forEach((g) => {
      map[g.college] = (map[g.college] || 0) + 1;
    });
    return Object.entries(map).map(([name, value]) => ({ name, value }));
  }, [graduates]);

  const todos = [
    { label: '待审核企业', count: pendingEnterprises, color: 'text-yellow-600', bg: 'bg-yellow-50' },
    { label: '待审核协议', count: pendingAgreements, color: 'text-blue-600', bg: 'bg-blue-50' },
    { label: '待办理派遣', count: pendingDispatches, color: 'text-red-600', bg: 'bg-red-50' },
    { label: '待就业毕业生', count: unemployedCount, color: 'text-slate-600', bg: 'bg-slate-50' },
  ];

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-lg font-bold text-slate-900">仪表盘</h2>
        <span className="text-xs text-slate-500">数据实时更新</span>
      </div>

      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <StatCard
          title="毕业生总数"
          value={graduates.length}
          icon={Users}
          color="teal"
          trend="较上月 +4"
          trendUp
        />
        <StatCard
          title="已就业人数"
          value={employedCount}
          icon={TrendingUp}
          color="blue"
          trend={`就业率 ${Math.round((employedCount / graduates.length) * 100)}%`}
          trendUp
        />
        <StatCard
          title="入驻企业"
          value={enterprises.length}
          icon={Building2}
          color="purple"
        />
        <StatCard
          title="在招岗位"
          value={jobs.filter((j) => j.status === 'published').length}
          icon={Briefcase}
          color="orange"
        />
      </div>

      <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
        <div className="rounded-xl border border-slate-100 bg-white p-5 shadow-sm lg:col-span-2">
          <h3 className="mb-4 text-sm font-semibold text-slate-800">各学院毕业生分布</h3>
          <div className="h-72">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={collegeData} margin={{ top: 8, right: 16, bottom: 8, left: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="name" tick={{ fontSize: 11 }} interval={0} angle={20} textAnchor="start" height={60} />
                <YAxis tick={{ fontSize: 11 }} />
                <Tooltip />
                <Bar dataKey="value" fill="#0d9488" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="rounded-xl border border-slate-100 bg-white p-5 shadow-sm">
          <h3 className="mb-4 text-sm font-semibold text-slate-800">毕业生就业状态分布</h3>
          <div className="h-56">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={statusData}
                  cx="50%"
                  cy="50%"
                  innerRadius={50}
                  outerRadius={80}
                  paddingAngle={3}
                  dataKey="value"
                >
                  {statusData.map((_, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend layout="vertical" verticalAlign="middle" align="right" wrapperStyle={{ fontSize: 12 }} />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
        <div className="rounded-xl border border-slate-100 bg-white p-5 shadow-sm lg:col-span-2">
          <h3 className="mb-4 flex items-center gap-2 text-sm font-semibold text-slate-800">
            <ClipboardList size={16} className="text-teal-600" />
            最新就业跟踪记录
          </h3>
          <div className="space-y-3">
            {tracking.slice(-5).reverse().map((t) => {
              const g = graduates.find((x) => x.id === t.graduateId);
              return (
                <div key={t.id} className="flex items-start gap-3 rounded-lg border border-slate-100 p-3">
                  <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-teal-50 text-teal-600 text-xs font-bold">
                    {g?.name?.[0] ?? '访'}
                  </div>
                  <div className="flex-1">
                    <p className="text-sm font-medium text-slate-800">
                      {g?.name ?? '未知'} · {employmentStatusLabels[t.status]}
                    </p>
                    <p className="mt-0.5 text-xs text-slate-500">{t.note}</p>
                  </div>
                  <span className="text-xs text-slate-400">{t.trackDate}</span>
                </div>
              );
            })}
          </div>
        </div>

        <div className="rounded-xl border border-slate-100 bg-white p-5 shadow-sm">
          <h3 className="mb-4 flex items-center gap-2 text-sm font-semibold text-slate-800">
            <AlertCircle size={16} className="text-red-500" />
            待办事项
          </h3>
          <div className="space-y-3">
            {todos.map((todo) => (
              <div
                key={todo.label}
                className="flex items-center justify-between rounded-lg border border-slate-100 p-3"
              >
                <div className="flex items-center gap-3">
                  <span className={`flex h-8 w-8 items-center justify-center rounded-full ${todo.bg} ${todo.color}`}>
                    {todo.count}
                  </span>
                  <span className="text-sm text-slate-700">{todo.label}</span>
                </div>
              </div>
            ))}
          </div>

          <div className="mt-6 rounded-lg bg-slate-50 p-4">
            <p className="text-xs text-slate-500">协议签约概况</p>
            <div className="mt-3 space-y-2">
              {agreements.slice(0, 3).map((a) => {
                const g = graduates.find((x) => x.id === a.graduateId);
                const e = enterprises.find((x) => x.id === a.enterpriseId);
                return (
                  <div key={a.id} className="flex items-center justify-between text-xs">
                    <span className="text-slate-700">{g?.name} → {e?.name}</span>
                    <span className="rounded px-1.5 py-0.5 bg-slate-200 text-slate-600">
                      {agreementStatusLabels[a.status]}
                    </span>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
