import { useMemo } from 'react';
import {
  PieChart,
  Pie,
  Cell,
  ResponsiveContainer,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
  Legend,
  LineChart,
  Line,
} from 'recharts';
import { useAppStore } from '@/stores/appStore';
import { employmentStatusLabels } from '@/types';

const COLORS = ['#0d9488', '#3b82f6', '#8b5cf6', '#f59e0b', '#ef4444', '#10b981'];

export function Statistics() {
  const { graduates, enterprises, agreements, jobs } = useAppStore();

  const statusData = useMemo(() => {
    const map: Record<string, number> = {};
    graduates.forEach((g) => { map[g.status] = (map[g.status] || 0) + 1; });
    return Object.entries(map).map(([key, value]) => ({
      name: employmentStatusLabels[key as keyof typeof employmentStatusLabels] ?? key,
      value,
    }));
  }, [graduates]);

  const collegeData = useMemo(() => {
    const map: Record<string, { total: number; employed: number }> = {};
    graduates.forEach((g) => {
      if (!map[g.college]) map[g.college] = { total: 0, employed: 0 };
      map[g.college].total += 1;
      if (g.status === 'employed') map[g.college].employed += 1;
    });
    return Object.entries(map).map(([name, v]) => ({
      name,
      total: v.total,
      employed: v.employed,
      rate: Math.round((v.employed / v.total) * 100),
    }));
  }, [graduates]);

  const industryData = useMemo(() => {
    const map: Record<string, number> = {};
    enterprises.forEach((e) => { map[e.industry] = (map[e.industry] || 0) + 1; });
    return Object.entries(map).map(([name, value]) => ({ name, value }));
  }, [enterprises]);

  const salaryData = useMemo(() => {
    const buckets = [
      { name: '10K以下', count: 0 },
      { name: '10-15K', count: 0 },
      { name: '15-20K', count: 0 },
      { name: '20-25K', count: 0 },
      { name: '25K以上', count: 0 },
    ];
    agreements.forEach((a) => {
      const salary = Number(a.salary);
      if (salary < 10000) buckets[0].count += 1;
      else if (salary < 15000) buckets[1].count += 1;
      else if (salary < 20000) buckets[2].count += 1;
      else if (salary < 25000) buckets[3].count += 1;
      else buckets[4].count += 1;
    });
    return buckets;
  }, [agreements]);

  const trendData = [
    { month: '6月', rate: 45 },
    { month: '7月', rate: 52 },
    { month: '8月', rate: 61 },
    { month: '9月', rate: 68 },
    { month: '10月', rate: 74 },
    { month: '11月', rate: 82 },
    { month: '12月', rate: 88 },
  ];

  return (
    <div className="space-y-6">
      <h2 className="text-lg font-bold text-slate-900">数据统计</h2>

      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
        <div className="rounded-xl border border-slate-100 bg-white p-5 shadow-sm">
          <h3 className="mb-4 text-sm font-semibold text-slate-800">毕业生就业状态分布</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={statusData} cx="40%" cy="50%" outerRadius={80} dataKey="value" label>
                  {statusData.map((_, i) => (
                    <Cell key={i} fill={COLORS[i % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend layout="vertical" verticalAlign="middle" align="right" wrapperStyle={{ fontSize: 12 }} />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="rounded-xl border border-slate-100 bg-white p-5 shadow-sm">
          <h3 className="mb-4 text-sm font-semibold text-slate-800">企业行业分布</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={industryData} cx="40%" cy="50%" innerRadius={50} outerRadius={80} dataKey="value" paddingAngle={3}>
                  {industryData.map((_, i) => (
                    <Cell key={i} fill={COLORS[i % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend layout="vertical" verticalAlign="middle" align="right" wrapperStyle={{ fontSize: 12 }} />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      <div className="rounded-xl border border-slate-100 bg-white p-5 shadow-sm">
        <h3 className="mb-4 text-sm font-semibold text-slate-800">各学院就业率统计</h3>
        <div className="h-72">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={collegeData} margin={{ top: 8, right: 16, bottom: 8, left: 0 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
              <XAxis dataKey="name" tick={{ fontSize: 11 }} interval={0} angle={20} textAnchor="start" height={60} />
              <YAxis tick={{ fontSize: 11 }} />
              <Tooltip />
              <Legend wrapperStyle={{ fontSize: 12 }} />
              <Bar dataKey="total" name="毕业生总数" fill="#94a3b8" radius={[4, 4, 0, 0]} />
              <Bar dataKey="employed" name="已就业人数" fill="#0d9488" radius={[4, 4, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
        <div className="rounded-xl border border-slate-100 bg-white p-5 shadow-sm">
          <h3 className="mb-4 text-sm font-semibold text-slate-800">签约薪资分布</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={salaryData} margin={{ top: 8, right: 16, bottom: 8, left: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="name" tick={{ fontSize: 11 }} />
                <YAxis tick={{ fontSize: 11 }} />
                <Tooltip />
                <Bar dataKey="count" name="人数" fill="#3b82f6" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="rounded-xl border border-slate-100 bg-white p-5 shadow-sm">
          <h3 className="mb-4 text-sm font-semibold text-slate-800">就业落实率趋势</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={trendData} margin={{ top: 8, right: 16, bottom: 8, left: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="month" tick={{ fontSize: 11 }} />
                <YAxis tick={{ fontSize: 11 }} domain={[0, 100]} />
                <Tooltip formatter={(v) => [`${v}%`, '落实率']} />
                <Line type="monotone" dataKey="rate" name="就业落实率" stroke="#0d9488" strokeWidth={3} dot={{ r: 4 }} />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4 sm:grid-cols-4">
        <div className="rounded-xl border border-slate-100 bg-white p-4 text-center shadow-sm">
          <p className="text-2xl font-bold text-teal-600">{graduates.length}</p>
          <p className="text-xs text-slate-500">毕业生总数</p>
        </div>
        <div className="rounded-xl border border-slate-100 bg-white p-4 text-center shadow-sm">
          <p className="text-2xl font-bold text-blue-600">
            {Math.round((graduates.filter((g) => g.status === 'employed').length / graduates.length) * 100)}%
          </p>
          <p className="text-xs text-slate-500">整体就业率</p>
        </div>
        <div className="rounded-xl border border-slate-100 bg-white p-4 text-center shadow-sm">
          <p className="text-2xl font-bold text-purple-600">{agreements.filter((a) => a.status === 'signed').length}</p>
          <p className="text-xs text-slate-500">已签约人数</p>
        </div>
        <div className="rounded-xl border border-slate-100 bg-white p-4 text-center shadow-sm">
          <p className="text-2xl font-bold text-orange-600">{jobs.filter((j) => j.status === 'published').length}</p>
          <p className="text-xs text-slate-500">在招岗位数</p>
        </div>
      </div>
    </div>
  );
}
