export type EmploymentStatus = 'unemployed' | 'employed' | 'further_study' | 'entrepreneurship' | 'flexible_employment';
export type EnterpriseStatus = 'pending' | 'approved' | 'rejected';
export type JobStatus = 'published' | 'unpublished' | 'closed';
export type AgreementStatus = 'draft' | 'submitted' | 'approved' | 'signed';
export type DispatchStatus = 'pending' | 'processed' | 'completed';

export interface User {
  id: string;
  username: string;
  name: string;
  role: 'admin';
}

export interface Graduate {
  id: string;
  studentId: string;
  name: string;
  gender: 'male' | 'female';
  college: string;
  major: string;
  class: string;
  phone: string;
  email: string;
  status: EmploymentStatus;
  graduationYear: string;
  createdAt: string;
}

export interface Enterprise {
  id: string;
  name: string;
  industry: string;
  scale: string;
  contactPerson: string;
  contactPhone: string;
  status: EnterpriseStatus;
  applyDate: string;
}

export interface Job {
  id: string;
  enterpriseId: string;
  title: string;
  department: string;
  salary: string;
  location: string;
  requirements: string;
  status: JobStatus;
  publishDate: string;
}

export interface Agreement {
  id: string;
  graduateId: string;
  enterpriseId: string;
  jobId: string;
  signDate: string;
  status: AgreementStatus;
  salary: string;
  workLocation: string;
}

export interface Dispatch {
  id: string;
  agreementId: string;
  graduateId: string;
  dispatchDate: string;
  certificateNo: string;
  destination: string;
  status: DispatchStatus;
}

export interface TrackingRecord {
  id: string;
  graduateId: string;
  trackDate: string;
  status: EmploymentStatus;
  note: string;
  contactResult: 'reachable' | 'unreachable' | 'no_answer';
}

export interface SystemSettings {
  systemName: string;
  currentYear: string;
}

export interface AppData {
  user: User | null;
  graduates: Graduate[];
  enterprises: Enterprise[];
  jobs: Job[];
  agreements: Agreement[];
  dispatches: Dispatch[];
  tracking: TrackingRecord[];
  settings: SystemSettings;
}

