import type { AppData, User, SystemSettings } from '@/types';
import {
  defaultSettings,
  mockGraduates,
  mockEnterprises,
  mockJobs,
  mockAgreements,
  mockDispatches,
  mockTracking,
} from '@/utils/mockData';

const STORAGE_KEY = 'campus_employment_data';

export const defaultData: AppData = {
  user: null,
  graduates: mockGraduates,
  enterprises: mockEnterprises,
  jobs: mockJobs,
  agreements: mockAgreements,
  dispatches: mockDispatches,
  tracking: mockTracking,
  settings: defaultSettings,
};

export function loadData(): AppData {
  if (typeof window === 'undefined') {
    return defaultData;
  }
  const raw = localStorage.getItem(STORAGE_KEY);
  if (!raw) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(defaultData));
    return defaultData;
  }
  try {
    return { ...defaultData, ...JSON.parse(raw) };
  } catch {
    return defaultData;
  }
}

export function saveData(data: Partial<AppData>): void {
  if (typeof window === 'undefined') return;
  const current = loadData();
  const next = { ...current, ...data };
  localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
}

export function setUser(user: User | null): void {
  saveData({ user });
}

export function updateSettings(settings: SystemSettings): void {
  saveData({ settings });
}

export function resetData(): void {
  if (typeof window === 'undefined') return;
  localStorage.setItem(STORAGE_KEY, JSON.stringify({
    ...defaultData,
    user: null,
  }));
}

export function generateId(prefix: string): string {
  return `${prefix}${Date.now().toString(36)}${Math.random().toString(36).slice(2, 7)}`;
}
