import { useState, useMemo } from 'react';
import { Plus, Search, Pencil, Trash2, CheckCircle, Printer } from 'lucide-react';
import { DataTable, type Column } from '@/components/DataTable';
import { Modal } from '@/components/Modal';
import { StatusBadge } from '@/components/StatusBadge';
import { useAppStore } from '@/stores/appStore';
import type { Dispatch, DispatchStatus } from '@/types';
import { dispatchStatusLabels } from '@/types';

const initialForm: Partial<Dispatch> = {
  agreementId: '',
  graduateId: '',
  dispatchDate: new Date().toISOString().slice(0, 10),
  certificateNo: '',
  destination: '',
  status: 'pending',
};

const PAGE_SIZE = 6;

export function Dispatch() {
  const { dispatches, agreements, graduates, addDispatch, updateDispatch, deleteDispatch } = useAppStore();
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('');
  const [page, setPage] = useState(1);
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<Dispatch | null>(null);
  const [form, setForm] = useState<Partial<Dispatch>>(initialForm);

  const signedAgreements = useMemo(() => agreements.filter((a) => a.status === 'signed'), [agreements]);

  const filtered = useMemo(() => {
    return dispatches.filter((d) => {
      const g = graduates.find((x) => x.id === d.graduateId);
      const matchSearch = g?.name.includes(search) ?? false;
      const matchStatus = statusFilter ? d.status === statusFilter : true;
      return matchSearch && matchStatus;
    });
  }, [dispatches, graduates, search, statusFilter]);

  const paged = useMemo(() => filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE), [filtered, page]);

  const openCreate = () => {
    setEditing(null);
    const first = signedAgreements[0];
    setForm({
      ...initialForm,
      agreementId: first?.id ?? '',
      graduateId: first?.graduateId ?? '',
    });
    setModalOpen(true);
  };

  const openEdit = (d: Dispatch) => {
    setEditing(d);
    setForm(d);
    setModalOpen(true);
  };

  const handleSubmit = (ev: React.FormEvent) => {
    ev.preventDefault();
    const agreement = agreements.find((a) => a.id === form.agreementId);
    const payload = { ...form, graduateId: agreement?.graduateId ?? form.graduateId };
    if (editing) {
      updateDispatch(editing.id, payload);
    } else {
      addDispatch(payload as Omit<Dispatch, 'id'>);
    }
    setModalOpen(false);
    setForm(initialForm);
    setEditing(null);
  };

  const handleDelete = (id: string) => {
    if (confirm('确定删除该派遣记录吗？')) deleteDispatch(id);
  };

  const handleProcess = (id: string) => updateDispatch(id, { status: 'processed' });
  const handleComplete = (id: string) => updateDispatch(id, { status: 'completed' });

  const columns: Column<Dispatch>[] = [
    { key: 'certificateNo', title: '报到证号' },
    {
      key: 'graduate',
      title: '毕业生',
      render: (d) => graduates.find((g) => g.id === d.graduateId)?.name ?? '-',
    },
    {
      key: 'agreement',
      title: '关联协议',
      render: (d) => `协议-${d.agreementId.slice(-4)}`,
    },
    { key: 'dispatchDate', title: '派遣日期' },
    { key: 'destination', title: '派遣去向' },
    {
      key: 'status',
      title: '办理状态',
      render: (d) => <StatusBadge status={d.status} label={dispatchStatusLabels[d.status]} />,
    },
  ];

  return (
    <div className="space-y-5">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <h2 className="text-lg font-bold text-slate-900">派遣办理</h2>
        <button
          onClick={openCreate}
          className="flex items-center justify-center gap-1.5 rounded-lg bg-teal-600 px-4 py-2 text-sm font-medium text-white hover:bg-teal-700"
        >
          <Plus size={16} /> 新增派遣
        </button>
      </div>

      <div className="flex flex-col gap-3 sm:flex-row">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input
            type="text"
            value={search}
            onChange={(e) => { setSearch(e.target.value); setPage(1); }}
            placeholder="搜索毕业生姓名..."
            className="w-full rounded-lg border border-slate-200 py-2 pl-10 pr-4 text-sm outline-none focus:border-teal-500 focus:ring-2 focus:ring-teal-500/20"
          />
        </div>
        <select
          value={statusFilter}
          onChange={(e) => { setStatusFilter(e.target.value); setPage(1); }}
          className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm outline-none focus:border-teal-500"
        >
          <option value="">全部状态</option>
          {Object.entries(dispatchStatusLabels).map(([key, label]) => (
            <option key={key} value={key}>{label}</option>
          ))}
        </select>
      </div>

      <DataTable
        columns={columns}
        data={paged}
        rowKey={(d) => d.id}
        actions={(d) => (
          <>
            {d.status === 'pending' && (
              <button
                onClick={() => handleProcess(d.id)}
                className="rounded-lg p-1.5 text-slate-500 hover:bg-blue-50 hover:text-blue-600"
                title="办理"
              >
                <CheckCircle size={16} />
              </button>
            )}
            {d.status === 'processed' && (
              <button
                onClick={() => handleComplete(d.id)}
                className="rounded-lg p-1.5 text-slate-500 hover:bg-green-50 hover:text-green-600"
                title="完成"
              >
                <CheckCircle size={16} />
              </button>
            )}
            <button
              onClick={() => alert(`打印报到证：${d.certificateNo}`)}
              className="rounded-lg p-1.5 text-slate-500 hover:bg-teal-50 hover:text-teal-600"
              title="打印"
            >
              <Printer size={16} />
            </button>
            <button
              onClick={() => openEdit(d)}
              className="rounded-lg p-1.5 text-slate-500 hover:bg-teal-50 hover:text-teal-600"
              title="编辑"
            >
              <Pencil size={16} />
            </button>
            <button
              onClick={() => handleDelete(d.id)}
              className="rounded-lg p-1.5 text-slate-500 hover:bg-red-50 hover:text-red-600"
              title="删除"
            >
              <Trash2 size={16} />
            </button>
          </>
        )}
        pagination={{
          page,
          pageSize: PAGE_SIZE,
          total: filtered.length,
          onChange: setPage,
        }}
      />

      <Modal open={modalOpen} onClose={() => setModalOpen(false)} title={editing ? '编辑派遣' : '新增派遣'}>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="mb-1 block text-xs font-medium text-slate-600">关联协议</label>
            <select
              required
              value={form.agreementId}
              onChange={(e) => {
                const agreement = agreements.find((a) => a.id === e.target.value);
                setForm({ ...form, agreementId: e.target.value, graduateId: agreement?.graduateId ?? '' });
              }}
              className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
            >
              <option value="">请选择协议</option>
              {signedAgreements.map((a) => {
                const g = graduates.find((x) => x.id === a.graduateId);
                return (
                  <option key={a.id} value={a.id}>{`${g?.name ?? ''} - 协议${a.id.slice(-4)}`}</option>
                );
              })}
            </select>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="mb-1 block text-xs font-medium text-slate-600">报到证号</label>
              <input
                required
                value={form.certificateNo}
                onChange={(e) => setForm({ ...form, certificateNo: e.target.value })}
                className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
              />
            </div>
            <div>
              <label className="mb-1 block text-xs font-medium text-slate-600">派遣日期</label>
              <input
                type="date"
                value={form.dispatchDate}
                onChange={(e) => setForm({ ...form, dispatchDate: e.target.value })}
                className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
              />
            </div>
          </div>
          <div>
            <label className="mb-1 block text-xs font-medium text-slate-600">派遣去向</label>
            <input
              value={form.destination}
              onChange={(e) => setForm({ ...form, destination: e.target.value })}
              className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
            />
          </div>
          <div>
            <label className="mb-1 block text-xs font-medium text-slate-600">办理状态</label>
            <select
              value={form.status}
              onChange={(e) => setForm({ ...form, status: e.target.value as DispatchStatus })}
              className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
            >
              {Object.entries(dispatchStatusLabels).map(([key, label]) => (
                <option key={key} value={key}>{label}</option>
              ))}
            </select>
          </div>
          <div className="flex justify-end gap-3 pt-2">
            <button
              type="button"
              onClick={() => setModalOpen(false)}
              className="rounded-lg border border-slate-200 px-4 py-2 text-sm font-medium text-slate-600 hover:bg-slate-50"
            >
              取消
            </button>
            <button
              type="submit"
              className="rounded-lg bg-teal-600 px-4 py-2 text-sm font-medium text-white hover:bg-teal-700"
            >
              保存
            </button>
          </div>
        </form>
      </Modal>
    </div>
  );
}
