import { useState } from 'react';
import { RefreshCw, Save, Trash2 } from 'lucide-react';
import { useAppStore } from '@/stores/appStore';

export function Settings() {
  const { settings, updateSettings, resetAllData } = useAppStore();
  const [form, setForm] = useState(settings);

  const handleSave = () => {
    updateSettings(form);
    alert('设置已保存');
  };

  const handleReset = () => {
    if (confirm('确定重置所有数据吗？此操作将清空所有修改并恢复演示数据。')) {
      resetAllData();
      alert('数据已重置');
    }
  };

  return (
    <div className="space-y-6">
      <h2 className="text-lg font-bold text-slate-900">系统设置</h2>

      <div className="rounded-xl border border-slate-100 bg-white p-6 shadow-sm">
        <h3 className="mb-4 text-sm font-semibold text-slate-800">基础设置</h3>
        <div className="grid grid-cols-1 gap-5 sm:grid-cols-2">
          <div>
            <label className="mb-1 block text-xs font-medium text-slate-600">系统名称</label>
            <input
              value={form.systemName}
              onChange={(e) => setForm({ ...form, systemName: e.target.value })}
              className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
            />
          </div>
          <div>
            <label className="mb-1 block text-xs font-medium text-slate-600">当前学年</label>
            <input
              value={form.currentYear}
              onChange={(e) => setForm({ ...form, currentYear: e.target.value })}
              className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-500"
            />
          </div>
        </div>
        <div className="mt-6 flex justify-end">
          <button
            onClick={handleSave}
            className="flex items-center gap-1.5 rounded-lg bg-teal-600 px-4 py-2 text-sm font-medium text-white hover:bg-teal-700"
          >
            <Save size={16} /> 保存设置
          </button>
        </div>
      </div>

      <div className="rounded-xl border border-slate-100 bg-white p-6 shadow-sm">
        <h3 className="mb-4 text-sm font-semibold text-slate-800">数据管理</h3>
        <p className="text-xs text-slate-500">
          系统当前使用浏览器 LocalStorage 进行数据持久化。点击下方按钮可将所有数据恢复为初始演示状态。
        </p>
        <div className="mt-5 flex flex-col gap-3 sm:flex-row">
          <button
            onClick={handleReset}
            className="flex items-center justify-center gap-1.5 rounded-lg border border-red-200 bg-red-50 px-4 py-2 text-sm font-medium text-red-600 hover:bg-red-100"
          >
            <RefreshCw size={16} /> 重置演示数据
          </button>
          <button
            onClick={() => {
              localStorage.removeItem('campus_employment_data');
              alert('本地数据已清空，刷新页面后重新初始化');
            }}
            className="flex items-center justify-center gap-1.5 rounded-lg border border-slate-200 px-4 py-2 text-sm font-medium text-slate-600 hover:bg-slate-50"
          >
            <Trash2 size={16} /> 清空本地缓存
          </button>
        </div>
      </div>

      <div className="rounded-xl border border-slate-100 bg-white p-6 shadow-sm">
        <h3 className="mb-4 text-sm font-semibold text-slate-800">关于系统</h3>
        <div className="space-y-2 text-sm text-slate-600">
          <p>高校毕业生就业跟踪管理系统 v1.0</p>
          <p>技术栈：React + TypeScript + Vite + Tailwind CSS + Zustand + Recharts</p>
          <p>数据存储：浏览器 LocalStorage</p>
          <p>演示账号：admin / 123456</p>
        </div>
      </div>
    </div>
  );
}
